result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/pw-sort/app.js", "content": "const list = document.getElementById('list');
const orderInput = document.getElementById('order');
const liveRegion = document.getElementById('live-region');

function label(li) {
  return `Item ${li.dataset.item}`;
}

function items() {
  return [...list.children];
}

function sync() {
  // Boundary disabling
  for (const li of items()) {
    li.querySelector('[data-dir="up"]').disabled = !li.previousElementSibling;
    li.querySelector('[data-dir="down"]').disabled = !li.nextElementSibling;
  }

  // Mirror order into hidden input as comma-separated values
  orderInput.value = items().map((li) => li.dataset.item).join(',');
}

function announce(li) {
  const position = items().indexOf(li) + 1;
  liveRegion.textContent = `${label(li)}, position ${position} of ${items().length}`;
}

function focusButton(li, dir) {
  // Keep focus on the clicked button; fall back to its counterpart if it is now disabled.
  let btn = li.querySelector(`[data-dir="${dir}"]`);
  if (btn.disabled) btn = li.querySelector(`[data-dir="${dir === 'up' ? 'down' : 'up'}"]`);
  btn.focus();
}

function move(li, dir) {
  if (dir === 'up' && li.previousElementSibling) {
    list.insertBefore(li, li.previousElementSibling);
  } else if (dir === 'down' && li.nextElementSibling) {
    list.insertBefore(li.nextElementSibling, li);
  } else {
    return;
  }
  sync();
  announce(li);
  focusButton(li, dir);
}

for (const li of items()) {
  for (const dir of ['up', 'down']) {
    li.querySelector(`[data-dir="${dir}"]`).addEventListener('click', () => move(li, dir));
  }
}

sync();
"})
