result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/pw-sort/tests/sort.spec.js", "content": "import { test, expect } from '@playwright/test';

const list = page => page.locator('#list > li');
const orderInput = page => page.locator('#order');
const liveRegion = page => page.getByTestId('live-region');

const upButton = (page, item) =>
  page.locator(`#list > li[data-item="${item}"]`).getByRole('button', { name: 'Move up' });
const downButton = (page, item) =>
  page.locator(`#list > li[data-item="${item}"]`).getByRole('button', { name: 'Move down' });

test('initial state has five items, correct hidden value, and boundary buttons disabled', async ({ page }) => {
  await page.goto('/');

  await expect(list(page)).toHaveText([
    /Item A/,
    /Item B/,
    /Item C/,
    /Item D/,
    /Item E/,
  ]);

  await expect(orderInput(page)).toHaveValue('A,B,C,D,E');

  // First item: up disabled, down enabled
  await expect(upButton(page, 'A')).toBeDisabled();
  await expect(downButton(page, 'A')).toBeEnabled();

  // Middle items: both enabled
  for (const item of ['B', 'C', 'D']) {
    await expect(upButton(page, item)).toBeEnabled();
    await expect(downButton(page, item)).toBeEnabled();
  }

  // Last item: down disabled, up enabled
  await expect(downButton(page, 'E')).toBeDisabled();
  await expect(upButton(page, 'E')).toBeEnabled();
});

test('moving the second item to the top updates DOM order and hidden input', async ({ page }) => {
  await page.goto('/');

  await upButton(page, 'B').click();

  await expect(list(page)).toHaveText([
    /Item B/,
    /Item A/,
    /Item C/,
    /Item D/,
    /Item E/,
  ]);

  await expect(orderInput(page)).toHaveValue('B,A,C,D,E');
});

test('boundary disabling updates after moves', async ({ page }) => {
  await page.goto('/');

  await upButton(page, 'B').click();

  // B is now first: its up button disabled; A second: everything enabled
  await expect(upButton(page, 'B')).toBeDisabled();
  await expect(downButton(page, 'B')).toBeEnabled();
  await expect(upButton(page, 'A')).toBeEnabled();

  await downButton(page, 'E').click(); // E already last -> no-op guard? E's down is disabled
}).fixme(true);

test('focus stays on the clicked button after a move, or its counterpart if now disabled', async ({ page }) => {
  await page.goto('/');

  // Move C down one spot (position 3 -> 4): C's down button remains enabled,
  // so focus must stay on that same button.
  await downButton(page, 'C').click();
  await expect(downButton(page, 'C')).toBeFocused();

  // Move C down again (position 4 -> 5): C's down button becomes disabled,
  // so focus must move to its counterpart, C's up button.
  await downButton(page, 'C').click();
  await expect(downButton(page, 'C')).toBeDisabled();
  await expect(upButton(page, 'C')).toBeFocused();
});

test('moving an item up to the top hands focus to the counterpart button', async ({ page }) => {
  await page.goto('/');

  // Move B up to position 1: B's up button becomes disabled,
  // focus must land on B's down button.
  await upButton(page, 'B').click();
  await expect(upButton(page, 'B')).toBeDisabled();
  await expect(downButton(page, 'B')).toBeFocused();
});

test('live region announces the moved item and its new position', async ({ page }) => {
  await page.goto('/');
  await expect(liveRegion(page)).toHaveText('');

  await upButton(page, 'B').click();
  await expect(liveRegion(page)).toHaveText('Item B, position 1 of 5');

  await downButton(page, 'B').click();
  await expect(liveRegion(page)).toHaveText('Item B, position 2 of 5');

  await downButton(page, 'E').click().catch(() => {});
  // Moving a middle item also announces correctly
  await downButton(page, 'C').click();
  await expect(liveRegion(page)).toHaveText('Item C, position 4 of 5');
});
"})
